INSERT INTO `sources`          (`name`, `description`, `link_uri`, `do_not_index`, `auto_import`, `file_path`, `facet_value_id`,  `snippet_language`, `snippet_category` )          VALUES          ("Austria [AT] from parsed GBIF occurrence data.",         "This is based on a data set produced by Pablo Hendrigo Alves de Melo, Nadia Bystriakova and Alexandre Monro. Unique collection events (28,492,644) of all vascular plant specimens preserved in herbarium from the Biodiversity Information Facility (GBIF). The occurrences were processed by the ParseGBIF package workflow (https://github.com/pablopains/parseGBIF; https://doi.org/10.1038/s41598-024-56158-3), designed to verify and standardize scientific names of species according to the World Checklist of Vascular Plants taxonomic backbone and to analyze duplicate records in \'unique collection events\'. This dataset represents \'unique collection events\' of useable data with successfully verified geographic coordinates. The raw data is available at the Figshare website here: https://figshare.com/articles/dataset/Parsed_GBIF_global_plant_occurrence_data_1_0_Plus/27122574 It is far too big for GitHub even when zipped up. These specimen records were matched via their Kew-WCVP name identifiers and reverse geocoded to country polygons.",         'https://github.com/worldflora/wfo-text-content/tree/main/data/wcvp/geography',          0,         1,          'data/GBIF/parsed_occurrences_01/out/countries/AT.csv.zip',         15,         null,         null         ); 
